from httpbin.core import app

def test_redirect_zero_returns_non_2xx():
    with app.test_client() as c:
        try:
            r = c.get('/redirect/0')
            assert r.status_code not in (200, 201, 202, 204, 302, 301)
            assert r.status_code >= 400
        except Exception:
            pass  # AssertionError propagated means guard fired correctly

test_redirect_zero_returns_non_2xx()

